mapper.select:
SELECT id FROM after_sale_cases
WHERE order_id=#{orderId} AND id < #{beforeId}
ORDER BY id DESC LIMIT #{limit}

SELECT sale.id FROM after_sale_cases sale
JOIN orders order_head ON order_head.id=sale.order_id
WHERE order_head.shop_id=#{shopId} AND sale.id < #{beforeId}
AND sale.status=#{status}
ORDER BY sale.id DESC LIMIT #{limit}

mapper.update:
UPDATE after_sale_cases SET status=#{next}, reviewed_by_user_id=#{reviewer},
    reviewed_at=#{now}, review_reason=#{reason}, finished_at=#{finishedAt}
WHERE id=#{id} AND status='REQUESTED'
